insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('f7bc1d26-2c98-5f3a-972a-7503513b6c07', 'Château Margaux', 'France', 'Bordeaux', null, 'One of the four original First Growths named in the 1855 Bordeaux Classification, set in the Margaux appellation on the Left Bank of the Gironde.', array['Estate-grown fruit','Barrel aging in new French oak']::text[], array['Premier Grand Cru Classé (1855)']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('e014e2e5-75b6-591b-9f77-7c2484e83b10', 'Opus One Winery', 'USA', 'Napa Valley', 1979, 'Founded as a joint venture between Baron Philippe de Rothschild and Robert Mondavi to make a single Bordeaux-style blend in Oakville.', array['Single blended wine each vintage']::text[], array['Franco-American partnership']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('981e7b68-8308-5106-a5f7-fd9676cd9008', 'Cloudy Bay', 'New Zealand', 'Marlborough', 1985, 'Established in Marlborough in 1985; its Sauvignon Blanc helped bring New Zealand wine to international attention.', array['Cool-climate viticulture']::text[], array['Early Marlborough pioneer']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('2ba4d78a-ef02-525f-900a-4664c5182505', 'Château d''Esclans', 'France', 'Provence', null, 'A Provence estate acquired by Sacha Lichine in 2006, focused entirely on rosé.', array['Rosé specialist']::text[], array['Whispering Angel']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('74de36c8-a5af-5373-afcd-9d780ef2cb60', 'Moët & Chandon', 'France', 'Champagne', 1743, 'Founded in Épernay in 1743, Moët & Chandon is one of the largest Champagne houses and the producer of Dom Pérignon.', array['Traditional method','Multi-vintage blending']::text[], array['Founded 1743','Home of Dom Pérignon']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('dc8fb2ab-5691-569f-bdc1-c614676c2db2', 'Marchesi Antinori', 'Italy', 'Tuscany', 1385, 'The Antinori family has made wine in Florence since 1385. Tignanello, first released in the 1970s, was a pioneering ''Super Tuscan''.', array['Sangiovese aged in barrique']::text[], array['26 generations of winemaking']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('1bf068df-550c-5327-9420-66b7b06a8d1d', 'Tenuta San Guido', 'Italy', 'Tuscany', null, 'Home of Sassicaia, created by Marchese Mario Incisa della Rocchetta in Bolgheri; the first commercial vintage was 1968.', array['Bordeaux varieties on the Tuscan coast']::text[], array['Bolgheri Sassicaia has its own DOC']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('85f9b4f6-c506-5336-9c67-672ac4f3dcfb', 'Penfolds', 'Australia', 'South Australia', 1844, 'Founded in 1844 near Adelaide by Dr Christopher Rawson Penfold. Grange was created by winemaker Max Schubert, with 1951 as the first experimental vintage.', array['Multi-regional blending','American oak aging for Grange']::text[], array['Grange first made in 1951']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('d049dca8-d8cc-5260-8786-75f0fe4307bc', 'Catena Zapata', 'Argentina', 'Mendoza', 1902, 'Founded by Italian immigrant Nicola Catena in 1902. Nicolás Catena Zapata later pioneered high-altitude Malbec in Mendoza.', array['High-altitude vineyards']::text[], array['High-altitude Malbec research']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('04b45dc1-cf8d-512c-b814-5dba5b7abe2c', 'Kim Crawford', 'New Zealand', 'Marlborough', 1996, 'Started in 1996 by winemaker Kim Crawford, focusing on vibrant Marlborough Sauvignon Blanc.', array['Stainless steel fermentation']::text[], array[]::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('f4bb3b44-9ad0-52cd-bcf5-63be67b4ad50', 'Château d''Yquem', 'France', 'Bordeaux', null, 'The only Sauternes estate ranked Premier Cru Supérieur in the 1855 Classification, famous for botrytised sweet wines.', array['Hand harvest in successive passes (tries)']::text[], array['Premier Cru Supérieur (1855)']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('7b2bd7cb-caac-5273-a46d-00076e266e0a', 'Pio Cesare', 'Italy', 'Piedmont', 1881, 'A family winery in Alba since 1881, making Barolo and Barbaresco from Nebbiolo.', array['Traditional Nebbiolo blending across crus']::text[], array['Founded 1881 in Alba']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('0f582dc0-642f-50fc-9e64-2c0ec75f535c', 'Vega Sicilia', 'Spain', 'Ribera del Duero', 1864, 'Founded in 1864, Vega Sicilia is one of Spain''s most celebrated estates; Único is released only after long aging.', array['Extended barrel and bottle aging']::text[], array['Founded 1864']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('5326332a-7506-5ef1-b8b7-1f71a8605575', 'Marqués de Riscal', 'Spain', 'Rioja', 1858, 'One of Rioja''s historic bodegas, founded in Elciego in 1858.', array['Tempranillo aged in oak']::text[], array['Founded 1858']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('00537794-2199-52aa-845c-20591799f0c6', 'Dr. Loosen', 'Germany', 'Mosel', null, 'A family estate in the Mosel run by Ernst Loosen, known for Riesling from steep slate vineyards.', array['Steep-slope slate vineyards']::text[], array[]::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('ac5183a0-1f04-5262-9347-43e34b5bc276', 'Maison Louis Jadot', 'France', 'Burgundy', 1859, 'A Beaune-based Burgundy house founded in 1859.', array['Négociant and domaine wines']::text[], array['Founded 1859']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('679c6d83-b55c-5ff3-9350-e01df0b29e56', 'Domaine Leflaive', 'France', 'Burgundy', null, 'A benchmark Puligny-Montrachet domaine and an early adopter of biodynamic farming in Burgundy.', array['Biodynamic viticulture']::text[], array[]::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('17a81a94-dfae-5aff-8f15-9d67f212b5d7', 'Ridge Vineyards', 'USA', 'Santa Cruz Mountains', null, 'Ridge''s Monte Bello Cabernet was among the California wines in the 1976 Judgment of Paris tasting.', array['Ingredient labeling','Native yeast fermentations']::text[], array['1976 Judgment of Paris']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('fcbb6888-a8ea-5058-b402-8250493bc0f9', 'Caymus Vineyards', 'USA', 'Napa Valley', 1972, 'Founded by the Wagner family in Rutherford in 1972.', array['Ripe, plush Napa Cabernet style']::text[], array[]::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('fdf793ea-fc86-5c36-ada2-0138fb9e6457', 'Taylor''s (Taylor Fladgate)', 'Portugal', 'Douro', 1692, 'One of the oldest Port houses, founded in 1692.', array['Aged tawny Port blending']::text[], array['Founded 1692']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('2c8ecccd-f9ca-5505-a0ee-5e1d420b9cd9', 'Veuve Clicquot', 'France', 'Champagne', 1772, 'Founded in Reims in 1772 and shaped by Barbe-Nicole Ponsardin, the widow (veuve) Clicquot, who developed riddling.', array['Pinot Noir-led blends']::text[], array['Founded 1772']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('fe1176b0-93bd-56a4-97a8-f06916d6d6b7', 'Meiomi', 'USA', 'California', 2006, 'Created by Joe Wagner in 2006 as a coastal California Pinot Noir blend.', array['Multi-county coastal blending']::text[], array[]::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('87665151-2a93-534a-8b8e-b34f987d3999', 'La Crema', 'USA', 'Sonoma Coast', 1979, 'A Sonoma County winery founded in 1979, focused on cool-climate Chardonnay and Pinot Noir.', array['Cool-climate sites']::text[], array[]::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('9153789b-6289-563f-a79a-968fc824a9f8', 'Santa Margherita', 'Italy', 'Trentino-Alto Adige', 1935, 'Founded in 1935; in 1961 it was among the first to vinify Pinot Grigio as a white wine.', array['Pinot Grigio specialist']::text[], array['Pinot Grigio pioneer (1961)']::text[], 'editorial') on conflict (id) do nothing;
insert into public.wineries (id, name, country, region, founded_year, story, practices, highlights, source) values ('7754a8a7-e6f5-57f8-9f05-d29da00abd16', 'Gravner', 'Italy', 'Friuli-Venezia Giulia', null, 'Josko Gravner''s estate in Oslavia is known for skin-contact white wines fermented in buried clay amphorae.', array['Amphora fermentation','Extended skin contact']::text[], array['Orange wine pioneer']::text[], 'editorial') on conflict (id) do nothing;
